import { test, expect } from '@playwright/test';
import { readFile } from 'node:fs/promises';

test('invoice downloads as a PDF', async ({ page }, testInfo) => {
  // Configure baseURL and a test account that owns INV-1042.
  await page.goto('/billing/invoices/INV-1042');
  const pending = page.waitForEvent('download');
  await page.getByRole('button', { name: 'Download invoice' }).click();
  const download = await pending;
  expect(await download.failure()).toBeNull();
  expect(download.suggestedFilename()).toMatch(/\.pdf$/i);

  const file = testInfo.outputPath('invoice.pdf');
  await download.saveAs(file);
  const bytes = await readFile(file);
  expect(bytes.subarray(0, 5).toString()).toBe('%PDF-');
  // Next: parse and assert the invoice fields described below.
});
